 static void LongPaths(){string area=Area("long-target"),name=new string('a',245-area.Length-1-4)+".txt",target=Path.Combine(area,name);Check(target.Length==245,"Long target fixture length mismatch");Put(target,"before");var transaction=new FileSetTransaction(Path.Combine(root,"flat-transactions"),new[]{target});transaction.Write(target,"after");transaction.Rollback();Check(File.ReadAllText(target)=="before","Long legal target did not roll back");string impossible=Path.Combine(area,"new-parent",new string('x',270)+".txt");try{Files.Atomic(impossible,"never");throw new Exception("Overlong path accepted");}catch(PathTooLongException){}Check(!Directory.Exists(Path.Combine(area,"new-parent")),"Path preflight created a destination directory");}
 static void Identity(){var self=ProcessIdentity.Capture(System.Diagnostics.Process.GetCurrentProcess().Id);Check(ProcessIdentity.Matches(self),"Own process identity rejected");var stale=J.D(J.Parse(J.Text(self)));stale["createdUtcTicks"]="1";Check(!ProcessIdentity.Matches(stale),"PID reuse accepted");Check(!ProcessIdentity.Kill(stale,J.S(self,"exe")),"Stale identity killed process");Check(!ProcessIdentity.Matches(self,Path.Combine(root,"different.exe")),"Wrong image path accepted");}
 static object InitialIdentity(Process process,string expected,List<object> log,int timeout=1000){try{return ((Task<object>)typeof(Lifecycle).GetMethod("InitialBackendIdentity",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{process.Id,expected,process,(Action<object>)(entry=>log.Add(entry)),timeout})).GetAwaiter().GetResult();}catch(TargetInvocationException error){throw error.InnerException;}}
 static void InitialIdentityReady(){using(var process=Process.GetCurrentProcess()){var self=ProcessIdentity.Capture(process.Id);int reads=0;var log=new List<object>();ProcessIdentity.CaptureOverride=pid=>{reads++;return self;};var pending=(Task<object>)typeof(Lifecycle).GetMethod("InitialBackendIdentity",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{process.Id,J.S(self,"exe"),process,(Action<object>)(entry=>log.Add(entry)),1000});Check(pending.IsCompleted,"Ready process acquired a fixed startup delay");Check(J.N(pending.GetAwaiter().GetResult(),"pid")==process.Id&&reads==2&&log.Count==0,"Ready process identity changed");}}
 static void InitialIdentityLoading(){using(var process=Process.GetCurrentProcess()){var self=ProcessIdentity.Capture(process.Id);foreach(int failAt in new[]{0,1}){int reads=0;var log=new List<object>();ProcessIdentity.CaptureOverride=pid=>{if(reads++==failAt)throw new Win32Exception(299,"fixture main module not initialized");return self;};var identity=InitialIdentity(process,J.S(self,"exe"),log);Check(J.N(identity,"pid")==process.Id&&reads==(failAt==0?3:4),"Transient first or verification read did not recover");Check(log.Count==2&&J.S(log[0],"phase")=="backend-identity-retry"&&J.N(log[0],"nativeError")==299&&J.S(log[1],"phase")=="backend-identity-ready","Retry diagnostics lost the original module error");ProcessIdentity.CaptureOverride=null;}}}
 static void InitialIdentityMismatch(){using(var process=Process.GetCurrentProcess()){var self=ProcessIdentity.Capture(process.Id);foreach(var reason in new[]{"pid-mismatch","image-mismatch","creation-mismatch","identity-changed"}){int reads=0;var changed=J.D(J.Parse(J.Text(self)));if(reason=="pid-mismatch")changed["pid"]=process.Id+1;else if(reason=="image-mismatch")changed["exe"]=Path.Combine(root,"unrelated.exe");else changed["createdUtcTicks"]="1";var log=new List<object>();ProcessIdentity.CaptureOverride=pid=>{reads++;return reason=="identity-changed"&&reads==1?self:changed;};Fails(()=>InitialIdentity(process,J.S(self,"exe"),log),"无法确认 Terre 进程归属");Check(log.Count==1&&J.S(log[0],"reason")==reason&&J.N(log[0],"attempts")==1,"Mismatched identity was retried or accepted: "+reason);Check(!process.HasExited,"Identity failure terminated a process");ProcessIdentity.CaptureOverride=null;}}}
 static void InitialIdentityExited(){using(var child=Process.Start(new ProcessStartInfo(typeof(LifecycleReliabilityChecks).Assembly.Location,"--identity-child"){UseShellExecute=false,CreateNoWindow=true})){Check(child.WaitForExit(5000),"Owned identity fixture did not exit");int reads=0;ProcessIdentity.CaptureOverride=pid=>{reads++;throw new Exception("Exited process must not be captured");};var log=new List<object>();Fails(()=>InitialIdentity(child,"unused.exe",log),"无法确认 Terre 进程归属");Check(reads==0&&log.Count==1&&J.S(log[0],"reason")=="process-exited"&&J.N(log[0],"attempts")==1,"Exited backend retried or accepted");}}
 static void InitialIdentityRestricted(){using(var process=Process.GetCurrentProcess()){var self=ProcessIdentity.Capture(process.Id);var log=new List<object>();ProcessIdentity.CaptureOverride=pid=>{throw new Win32Exception(5,"fixture restricted read");};try{InitialIdentity(process,J.S(self,"exe"),log,50);throw new Exception("Restricted identity was accepted");}catch(IOException error){Check(error.InnerException is Win32Exception&&((Win32Exception)error.InnerException).NativeErrorCode==5,"Restricted read error was hidden");}var last=log.Last();Check(log.Count==2&&J.S(last,"reason")=="read-timeout"&&J.N(last,"nativeError")==5&&J.N(last,"attempts")>=2&&J.N(last,"elapsedMs")<1000,"Restricted read wait was unbounded or diagnostics lost");Check(!process.HasExited,"Restricted read terminated a process");}}
 static void InitialIdentityTimeout(){using(var process=Process.GetCurrentProcess()){var self=ProcessIdentity.Capture(process.Id);var log=new List<object>();ProcessIdentity.CaptureOverride=pid=>null;Fails(()=>InitialIdentity(process,J.S(self,"exe"),log,50),"无法确认 Terre 进程归属");Check(log.Count==2&&J.S(log.Last(),"reason")=="read-timeout"&&J.N(log.Last(),"attempts")>=2&&J.N(log.Last(),"elapsedMs")<1000,"Unreadable identity did not expire");Check(!process.HasExited,"Timeout terminated a process");}}
